def compute_total(cart, is_member):
    total = 0
    for item in cart:
        total += item.price * item.qty
    if is_member:
        total = total * 0.9
    return round(total, 2)

BASE_SHIPPING_RATE = 4.99


def get_shipping_cost(weight_kg, is_express):
    if weight_kg <= 1:
        cost = BASE_SHIPPING_RATE
    elif weight_kg <= 5:
        cost = BASE_SHIPPING_RATE * 2
    else:
        cost = BASE_SHIPPING_RATE * 3
    if is_express:
        cost += BASE_SHIPPING_RATE
    return round(cost, 2)

def classify(n):
    if n < 0:
        return "negative"
    if n == 0:
        return "zero"
    return "positive"

def add_item(item, cart=None):
    if cart is None:
        cart = []
    cart.append(item)
    return cart

def _validate_positive_amount(amount):
    if amount <= 0:
        raise ValueError("amount must be positive")


def charge_card(amount):
    _validate_positive_amount(amount)
    return amount


def refund_card(amount):
    _validate_positive_amount(amount)
    return -amount

def total_price(items):
    total = 0
    for index in range(len(items) - 1):
        total += items[index]
    return total

def compute_discounted(price, category):
    if category in ("electronics", "clothing"):
        if price > 100:
            return round(price * 0.9, 2)
        return round(price * 0.95, 2)
    else:
        return round(price * 0.95, 2)

_STATUS_MESSAGES = {
    200: "OK",
    201: "Created",
    404: "Not Found",
    500: "Internal Server Error",
}


def http_status_message(code):
    return _STATUS_MESSAGES.get(code, "Unknown Status")

def parse_priority(value):
    if value is None:
        raise ValueError("priority is required")

    normalized = str(value).strip().lower()
    if normalized not in ("low", "medium", "high"):
        raise ValueError("invalid priority: " + str(value))

    return normalized

MINIMUM_ORDER_THRESHOLD = 20


def calculate_invoice_total(subtotal, is_international):
    if subtotal < MINIMUM_ORDER_THRESHOLD:
        raise ValueError(f"subtotal below minimum of {MINIMUM_ORDER_THRESHOLD}")
    total = subtotal + subtotal * 0.05
    if is_international:
        total = total + 15.00
        total = total - 2.00
    return round(total, 2)
